void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno, resno;
    OPJ_UINT32 max_prec = 0, max_res = 0;
    OPJ_UINT32 dx_min = 0, dy_min = 0;

    *p_tx0 = p_cp->tx0 + (p_tileno % p_cp->tw) * p_cp->tdx;
    *p_tx1 = *p_tx0 + p_cp->tdx;
    *p_ty0 = p_cp->ty0 + (p_tileno / p_cp->tw) * p_cp->tdy;
    *p_ty1 = *p_ty0 + p_cp->tdy;

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        for (resno = 1; resno < p_cp->cp_tx0[compno].numresolution; ++resno) {
            OPJ_UINT32 dx = p_cp->cp_tx0[compno].resolutions[resno].pdx;
            OPJ_UINT32 dy = p_cp->cp_tx0[compno].resolutions[resno].pdy;

            if (resno > max_res) {
                max_res = resno;
            }

            if (dx < dx_min || dx_min == 0) {
                dx_min = dx;
            }

            if (dy < dy_min || dy_min == 0) {
                dy_min = dy;
            }

            if (resno > max_prec) {
                max_prec = resno;
            }
        }
    }

    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;

    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;

    OPJ_UINT32 num_resolutions;
    OPJ_UINT32 num_components = p_image->numcomps;

    OPJ_UINT32 tile_width = p_cp->tileno_x;
    OPJ_UINT32 tile_height = p_cp->tileno_y;

    OPJ_UINT32 tile_x = p_tileno % tile_width;
    OPJ_UINT32 tile_y = p_tileno / tile_width;

    *p_tx0 = (OPJ_INT32)(tile_x * p_image->x0);
    *p_tx1 = (OPJ_INT32)((tile_x + 1) * p_image->x0);
    if (*p_tx1 > (OPJ_INT32)p_image->x1)
        *p_tx1 = (OPJ_INT32)p_image->x1;

    *p_ty0 = (OPJ_INT32)(tile_y * p_image->y0);
    *p_ty1 = (OPJ_INT32)((tile_y + 1) * p_image->y0);
    if (*p_ty1 > (OPJ_INT32)p_image->y1)
        *p_ty1 = (OPJ_INT32)p_image->y1;

    for (compno = 0; compno < num_components; ++compno) {
        num_resolutions = p_cp->tcps[compno].num_resolutions;
        max_res = (max_res < num_resolutions) ? num_resolutions : max_res;

        for (resno = 0; resno < num_resolutions; ++resno) {
            OPJ_UINT32 dx = p_cp->tcps[compno].tx0[resno];
            OPJ_UINT32 dy = p_cp->tcps[compno].ty0[resno];

            dx_min = (dx_min < dx) ? dx_min : dx;
            dy_min = (dy_min < dy) ? dy_min : dy;
        }

        max_prec = (max_prec < p_cp->tcps[compno].num_resolutions) ? p_cp->tcps[compno].num_resolutions : max_prec;
    }

    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_precision = 0;
    OPJ_UINT32 max_resolutions = 0;
    OPJ_UINT32 dx_min = p_cp->tx0;
    OPJ_UINT32 dy_min = p_cp->ty0;

    OPJ_UINT32 tw = p_cp->tw;
    OPJ_UINT32 th = p_cp->th;
    OPJ_UINT32 x = p_cp->tx0;
    OPJ_UINT32 y = p_cp->ty0;

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        const opj_image_comp_t *comp = &p_image->comps[compno];
        const opj_tcp_t *tcp = &p_cp->tcps[compno];

        for (resno = 0; resno < tcp->numresolution; ++resno) {
            const opj_tcd_resolution_t *res = &tcp->tcd_resolutions[resno];

            if (res->x0 > x || res->y0 > y) {
                x = res->x0;
                y = res->y0;
            }

            if (res->x1 > x) {
                x = res->x1;
            }

            if (res->y1 > y) {
                y = res->y1;
            }

            if (res->dx < dx_min) {
                dx_min = res->dx;
            }

            if (res->dy < dy_min) {
                dy_min = res->dy;
            }

            if (resno + 1 > max_resolutions) {
                max_resolutions = resno + 1;
            }

            if (resno + 1 > max_precision) {
                max_precision = resno + 1;
            }
        }
    }

    *p_tx0 = (OPJ_INT32)(x + (p_tileno % tw) * p_cp->tdx);
    *p_tx1 = (OPJ_INT32)(x + (p_tileno % tw + 1) * p_cp->tdx);
    *p_ty0 = (OPJ_INT32)(y + (p_tileno / tw) * p_cp->tdy);
    *p_ty1 = (OPJ_INT32)(y + (p_tileno / tw + 1) * p_cp->tdy);
    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_precision;
    *p_max_res = max_resolutions;
}

void calculate_tile_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                               OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                               OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                               OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;

    *p_tx0 = 0;
    *p_tx1 = 0;
    *p_ty0 = 0;
    *p_ty1 = 0;
    *p_dx_min = 0;
    *p_dy_min = 0;
    *p_max_prec = 0;
    *p_max_res = 0;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        opj_tcp_t *tcp = &p_cp->tcp[p_tileno];
        opj_tccp_t *tccp = &tcp->tccps[compno];
        OPJ_UINT32 dx = 1;
        OPJ_UINT32 dy = 1;

        for (resno = 1; resno < tccp->numresolutions; resno++) {
            dx *= tccp->dx[resno - 1];
            dy *= tccp->dy[resno - 1];
        }

        if (*p_dx_min == 0 || dx < *p_dx_min) {
            *p_dx_min = dx;
        }

        if (*p_dy_min == 0 || dy < *p_dy_min) {
            *p_dy_min = dy;
        }

        if (tccp->numresolutions > *p_max_res) {
            *p_max_res = tccp->numresolutions;
        }

        if (tccp->numresolutions > *p_max_prec) {
            *p_max_prec = tccp->numresolutions;
        }
    }
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;

    *p_tx0 = p_cp->tx0 + (p_tileno % p_cp->tw) * p_cp->tdx;
    *p_tx1 = *p_tx0 + p_cp->tdx;
    if (*p_tx1 > (OPJ_INT32)p_image->x1) {
        *p_tx1 = p_image->x1;
    }

    *p_ty0 = p_cp->ty0 + (p_tileno / p_cp->tw) * p_cp->tdy;
    *p_ty1 = *p_ty0 + p_cp->tdy;
    if (*p_ty1 > (OPJ_INT32)p_image->y1) {
        *p_ty1 = p_image->y1;
    }

    *p_dx_min = 0;
    *p_dy_min = 0;
    *p_max_prec = 0;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        const opj_tcp_t *tcp = &p_cp->tcp[p_image->comps[compno].prec];
        OPJ_UINT32 dx_min_comp = 0;
        OPJ_UINT32 dy_min_comp = 0;
        OPJ_UINT32 max_prec_comp = 0;

        for (resno = 0; resno < tcp->numresolution; resno++) {
            const opj_tccp_t *tccp = &tcp->tccps[compno];
            OPJ_UINT32 dx = tccp->dx[resno];
            OPJ_UINT32 dy = tccp->dy[resno];

            if (resno == 0) {
                dx_min_comp = dx;
                dy_min_comp = dy;
            } else {
                dx_min_comp = (dx_min_comp < dx) ? dx_min_comp : dx;
                dy_min_comp = (dy_min_comp < dy) ? dy_min_comp : dy;
            }

            max_prec_comp = resno + 1;
        }

        if (compno == 0) {
            *p_dx_min = dx_min_comp;
            *p_dy_min = dy_min_comp;
        } else {
            *p_dx_min = (*p_dx_min < dx_min_comp) ? *p_dx_min : dx_min_comp;
            *p_dy_min = (*p_dy_min < dy_min_comp) ? *p_dy_min : dy_min_comp;
        }

        if (max_prec_comp > *p_max_prec) {
            *p_max_prec = max_prec_comp;
        }
    }

    *p_max_res = *p_max_prec;
}
